62	// Plans returns an organization's plans, oldest first.
63	func (s *Store) Plans(orgID string) []Plan {
64		s.mu.Lock()
65		defer s.mu.Unlock()
66		out := []Plan{}
67		for _, p := range s.plans {
68			if p.OrgID == orgID {
69				out = append(out, p)
70			}
71		}
72		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
73		return out
74	}
