1	// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
2	// float.
3	package money
4	
5	import (
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// Currency is an ISO 4217 currency code.
13	type Currency string
14	
15	// The currencies Tally bills in.
16	const (
17		USD Currency = "USD"
18		EUR Currency = "EUR"
19		GBP Currency = "GBP"
20		JPY Currency = "JPY"
21		KWD Currency = "KWD"
22	)
23	
24	var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}
25	
26	// Valid reports whether c is a currency Tally bills in.
27	func (c Currency) Valid() bool {
28		_, ok := symbols[c]
29		return ok
30	}
31	
32	// ErrInvalidAmount is returned for an amount that cannot be read.
33	var ErrInvalidAmount = errors.New("invalid amount")
34	
35	// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units.
36	func ParseMajor(s string, c Currency) (int64, error) {
37		if !c.Valid() {
38			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
39		}
40		s = strings.TrimSpace(s)
41		whole, frac, hasDot := strings.Cut(s, ".")
42		if whole == "" || (hasDot && frac == "") || len(frac) > 2 {
43			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
44		}
45		for _, r := range whole + frac {
46			if r < '0' || r > '9' {
47				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
48			}
49		}
50		for len(frac) < 2 {
51			frac += "0"
52		}
53		n, err := strconv.ParseInt(whole+frac, 10, 64)
54		if err != nil {
55			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
56		}
57		return n, nil
58	}
59	
60	// Format renders an amount for people: "$1,234.50", "-€0.99".
61	func Format(amount int64, c Currency) string {
62		sign := ""
63		if amount < 0 {
64			sign, amount = "-", -amount
65		}
66		whole, frac := amount/100, amount%100
67		return fmt.Sprintf("%s%s%s.%02d", sign, symbols[c], group(whole), frac)
68	}
69	
70	// group writes n with a comma between each group of three digits.
71	func group(n int64) string {
72		s := strconv.FormatInt(n, 10)
73		var b strings.Builder
74		for i, r := range s {
75			if i > 0 && (len(s)-i)%3 == 0 {
76				b.WriteByte(',')
77			}
78			b.WriteRune(r)
79		}
80		return b.String()
81	}
82	
83	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
84	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
85	
86	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
87	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
88	
89	// divRound divides and rounds half away from zero.
90	func divRound(num, den int64) int64 {
91		if (num < 0) != (den < 0) {
92			return -((abs(num) + abs(den)/2) / abs(den))
93		}
94		return (abs(num) + abs(den)/2) / abs(den)
95	}
96	
97	func abs(v int64) int64 {
98		if v < 0 {
99			return -v
100		}
101		return v
102	}
103

