// TiersMode says how a metered plan's tiers price usage.
type TiersMode string

// Tiers modes.
const (
	// Graduated prices each unit at the tier it falls in.
	Graduated TiersMode = "graduated"
	// Volume prices every unit at the tier the total usage falls in.
	Volume TiersMode = "volume"
)

// Tier is a band of usage on a metered plan. UpTo is the last unit it covers (inclusive); nil means no limit. Amounts are
// minor units. FlatAmount is charged once when a unit falls in the tier.
type Tier struct {
	UpTo       *int64 `json:"up_to"`
	UnitAmount int64  `json:"unit_amount"`
	FlatAmount int64  `json:"flat_amount"`
}

