// TieredAmount returns the charge for quantity units on a tiered plan, in minor units. Graduated: each unit is priced at the
// unit amount of the tier it falls in, and every tier that at least one unit falls in adds its flat amount. Volume: every
// unit is priced at the unit amount of the tier the quantity falls in, which adds its flat amount once. A tier's up_to is
// inclusive, and a quantity of 0 costs 0.
func TieredAmount(tiers []store.Tier, mode store.TiersMode, quantity int64) int64 {
	if quantity <= 0 || len(tiers) == 0 {
		return 0
	}
	if mode == store.Volume {
		tier := tiers[len(tiers)-1]
		for _, t := range tiers {
			if t.UpTo == nil || quantity <= *t.UpTo {
				tier = t
				break
			}
		}
		return quantity*tier.UnitAmount + tier.FlatAmount
	}
	var total, from int64 // from is the last unit before the tier
	remaining := quantity
	for _, t := range tiers {
		if remaining == 0 {
			break
		}
		units := remaining
		if t.UpTo != nil && *t.UpTo-from < units {
			units = *t.UpTo - from
		}
		total += units*t.UnitAmount + t.FlatAmount
		remaining -= units
		if t.UpTo != nil {
			from = *t.UpTo
		}
	}
	return total
}

