func TestTieredAmount(t *testing.T) {
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{{UpTo: upTo(10), UnitAmount: 100}, {UpTo: upTo(20), UnitAmount: 80, FlatAmount: 500}, {UnitAmount: 50}}
	for _, c := range []struct {
		name     string
		mode     store.TiersMode
		quantity int64
		want     int64
	}{
		{"graduated none", store.Graduated, 0, 0},
		{"graduated inside the first tier", store.Graduated, 7, 700},
		{"graduated up_to is inclusive", store.Graduated, 10, 1000},
		{"graduated into the second tier", store.Graduated, 15, 1000 + 5*80 + 500},
		{"graduated at the second tier's up_to", store.Graduated, 20, 1000 + 10*80 + 500},
		{"graduated into the open tier", store.Graduated, 25, 1000 + 10*80 + 500 + 5*50},
		{"volume none", store.Volume, 0, 0},
		{"volume inside the first tier", store.Volume, 10, 10 * 100},
		{"volume moves every unit to the second tier", store.Volume, 11, 11*80 + 500},
		{"volume at the second tier's up_to", store.Volume, 20, 20*80 + 500},
		{"volume into the open tier", store.Volume, 21, 21 * 50},
	} {
		if got := TieredAmount(tiers, c.mode, c.quantity); got != c.want {
			t.Errorf("%s: TieredAmount(%d) = %d, want %d", c.name, c.quantity, got, c.want)
		}
	}
}

func TestTieredAmountFlatAmountOnce(t *testing.T) {
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{{UpTo: upTo(5), FlatAmount: 300}, {UnitAmount: 10}}
	if got := TieredAmount(tiers, store.Graduated, 3); got != 300 {
		t.Errorf("graduated 3 = %d, want 300", got)
	}
	if got := TieredAmount(tiers, store.Graduated, 6); got != 300+10 {
		t.Errorf("graduated 6 = %d, want 310", got)
	}
}

