		{"up_to": nil, "unit_amount": "0.50"},
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "API", "currency": "USD", "interval": "month",
		"usage_type": "metered", "tiers_mode": "graduated", "tiers": tiers}, &p)
	if p.TiersMode != store.Graduated || len(p.Tiers) != 3 || p.Tiers[0].UpTo == nil || *p.Tiers[0].UpTo != 10 || p.Tiers[0].UnitAmount != 100 ||
		p.Tiers[1].FlatAmount != 500 || p.Tiers[2].UpTo != nil || p.Tiers[2].UnitAmount != 50 {
		t.Fatalf("plan = %+v", p)
	}
	bad := []map[string]any{
		{"tiers_mode": "graduated", "tiers": []any{}},
		{"tiers_mode": "stairs", "tiers": tiers},
		{"tiers": tiers},
		{"tiers_mode": "volume"},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": 20, "unit_amount": "1"}, {"up_to": 10, "unit_amount": "1"}, {"up_to": nil, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": 10, "unit_amount": "1"}, {"up_to": 5, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": 1.5, "unit_amount": "1"}, {"up_to": nil, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": "10", "unit_amount": "1"}, {"up_to": nil, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": 0, "unit_amount": "1"}, {"up_to": nil, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": nil, "unit_amount": "1"}, {"up_to": nil, "unit_amount": "1"}}},
		{"tiers_mode": "volume", "tiers": []map[string]any{{"up_to": 5, "unit_amount": "1"}}},
