		{"usage_type": "licensed", "price": "10", "tiers_mode": "volume", "tiers": tiers},
	}
	for _, in := range bad {
		in["name"], in["currency"], in["interval"], in["usage_type"] = "X", "USD", "month", firstNonEmpty(in["usage_type"], "metered")
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, in); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Fatalf("%v: %s", in, r)
