func TestTieredUsageIsBilledOnRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	upTo := int64(100)
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, Interval: store.Monthly, UsageType: store.Metered,
		TiersMode: store.Volume, Tiers: []store.Tier{{UpTo: &upTo, UnitAmount: 2}, {UnitAmount: 1, FlatAmount: 500}}}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{60, start}, {70, start.Add(48 * time.Hour)}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	// 130 units is past the first tier, so volume pricing charges all 130 at 1 and the open tier's flat amount of 500.
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 1 || invs[0].Lines[0].UnitAmount != 130+500 ||
		!strings.HasPrefix(invs[0].Lines[0].Description, "API calls") || !invs[0].PeriodEnd.Equal(end) {
		t.Fatalf("invoices = %+v", invs)
	}
	// The next period has no usage, so renewing it invoices nothing.
	next, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	e.Clock.Set(next.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a period with no usage was invoiced: %+v", invs)
	}
}

